const $=s=>document.querySelector(s),sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(n=>n.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','panels.js','deck-midi.js','midi.js','loop-pads.js','instant-double.js','effects.js','extended-effects.js','styles.css','midi-everyday-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f)).arrayBuffer())])));
async function until(fn,label,ms=12000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
const click=s=>{assert($(s),'Missing '+s);$(s).click();},field=(s,v)=>{assert($(s),'Missing '+s);$(s).value=String(v);};
const button=(n,a)=>`[data-deck="${n}"][data-action="${a}"]`;
function add(target,ch,n){field('#midi-target',target);field('#midi-type','Note');field('#midi-channel',ch);field('#midi-number',n);field('#midi-encoding','7-bit absolute');click('#midi-add');}
function send(ch,n,value=127){field('#midi-type','Note');field('#midi-channel',ch);field('#midi-number',n);field('#midi-test-value',value);click('#midi-send');}
function press(ch,n){send(ch,n);send(ch,n,0);}
function base64(b){let s='';for(let i=0;i<b.length;i+=16384)s+=String.fromCharCode(...b.subarray(i,i+16384));return btoa(s);}
function measure(data,sr,from,to){let power=0;const crossings=[],start=Math.ceil(from*sr),end=Math.floor(to*sr);assert(start>=0&&end<=data.length&&end>start,'Invalid measurement window');for(let i=start;i<end;i++){power+=data[i]**2;if(i>start&&data[i-1]<0&&data[i]>=0)crossings.push((i-1-data[i-1]/(data[i]-data[i-1]))/sr);}return{from,to,rms:Math.sqrt(power/(end-start)),hz:crossings.length>3?(crossings.length-1)/(crossings.at(-1)-crossings[0]):null};}
let app;
async function run(){
 $('#everyday-run').disabled=true;const {engine,state}=app,source=state.decks[0],target=state.decks[1],original=source.track,other=target.track;
 const report={startedAt:new Date().toISOString(),completed:false,scope:'Actual app MIDI editor/synthetic input, library/Prepare/fixed loop/Instant Double/FX actions and recorded master. No physical/native/full transport/FX/reference acceptance.',criteria:{frequencyErrorHz:.8,playingMinimumRMS:.005,doubleClockDifferenceSeconds:.003,doubleAmplitudeRatio:[1.85,2.15],tailMinimumRMS:.0001},events:[],checks:[],errors:[]};
 const configureFX=engine.configureFX.bind(engine);report.fxCalls=[];engine.configureFX=(...args)=>{report.fxCalls.push({time:engine.ctx?.currentTime,slots:args[0].map(bank=>bank.map(slot=>({name:slot.name,on:slot.on,depth:slot.depth,beat:slot.beat}))),bpms:args[2],stack:new Error().stack.split('\n').slice(1,4)});return configureFX(...args);};
 const event=name=>{const e={name,time:engine.ctx.currentTime-engine.recordStarted};report.events.push(e);return e;};
 const cc=(ch,n,value)=>{field('#midi-type','CC');field('#midi-channel',ch);field('#midi-number',n);field('#midi-test-value',value);click('#midi-send');};
 try{
  report.sourceBefore=await identities();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical mute');await until(()=>!state.analysis,'Initial analysis');state.settings['Lock Playing Deck']=false;state.settings['Instant Doubles']=false;state.prepare=[];
  for(const [track,freq]of [[original,330],[other,550]]){const b=engine.ctx.createBuffer(2,engine.ctx.sampleRate*20,engine.ctx.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=.1*Math.sin(2*Math.PI*freq*i/engine.ctx.sampleRate);engine.buffers.set(track.id,b);Object.assign(track,{bpm:120,grid:0,gridWarpMarkers:[],duration:20,analyzed:true,sampleGain:0});}
  for(const d of [source,target]){Object.assign(d,{rate:1,position:0,keylock:false,keyShift:0,reverse:false,loop:false,stemSlip:'off',slip:false,sync:false,level:.8});engine.clearDeckScratchCache(d.index);engine.mix(d.index,'level',.8);}
  click('[data-panel="midi"]');click('#midi-reset');for(const [name,ch,n]of [['Library focus',1,0],['Prepare add',1,3],['Prepare open',4,3],['Deck 1 auto loop four',2,3],['Deck 2 load',3,13],['FX unit 1 next',5,0],['FX unit 1 enable',2,0]])add(name,ch,n);
  for(const [name,ch,n,encoding]of [['Library browse',1,1,'Relative two’s complement'],['Library fast browse',4,1,'Relative two’s complement'],['FX unit 1 select',5,6,'7-bit absolute']]){field('#midi-target',name);field('#midi-type','CC');field('#midi-channel',ch);field('#midi-number',n);field('#midi-encoding',encoding);click('#midi-add');}
  press(1,0);await until(()=>state.browserFocus==='crates','Crate focus');cc(1,1,1);await until(()=>state.crate==='itunes','Browse real crate list');assert($('#crates').classList.contains('midi-focused'),'Crate focus outline missing');press(1,0);await until(()=>state.browserFocus==='tracks','Track focus');const before=state.selected;cc(4,1,1);await until(()=>state.selected!==before,'Fast track browse');const selected=state.selected;press(1,3);await until(()=>state.prepare.includes(selected),'Prepare add');assert(JSON.parse(localStorage.getItem('openplay-review-v1')).prepare.includes(selected),'Prepare did not persist');press(4,3);await until(()=>state.panel==='prepare'&&!$('#panel').hidden,'Prepare open');assert($(`[data-prepare-load="${selected}"]`),'Prepare actual row missing');report.library={crate:state.crate,focus:state.browserFocus,selected,prepare:[...state.prepare]};
  await engine.seek(source,1);press(2,3);await until(()=>source.loop,'Fixed four-beat Loop');report.fixedLoop={in:source.loopIn,out:source.loopOut,beatJumpSetting:state.settings['Show Beat Jump Controls']};assert(source.loopOut-source.loopIn===2,'Fixed4 loop used Beat Jump lower-row action');press(2,3);await until(()=>!source.loop,'Fixed Loop off');
  click('#modal-close');click(button(0,'play'));await until(()=>source.playing,'Source normal Play');await engine.recordStart();const single=event('single-source');await sleep(300);state.selected=other.id;click('[data-panel="midi"]');press(3,13);await sleep(40);press(3,13);await until(()=>target.track===original&&target.playing&&!target.processing,'Double Load starts aligned target');await until(()=>engine.ctx.currentTime>=target.anchorTime+.02,'Double audible scheduled start');report.double={sourcePosition:engine.position(source),targetPosition:engine.position(target),rate:[source.rate,target.rate],playing:[source.playing,target.playing]};assert(Math.abs(report.double.sourcePosition-report.double.targetPosition)<.003,'Double playheads diverged');const doubled=event('double-source');await sleep(300);
  click('#modal-close');click(button(0,'play'));click(button(1,'play'));await until(()=>!source.playing&&!target.playing,'Stop double');click('[data-panel="midi"]');cc(5,6,0);await until(()=>state.fx[0][0].name==='LPF','Absolute FX select');press(5,0);await until(()=>state.fx[0][0].name==='Delay','Shift FX On selects next actual effect');assert(!state.fx[0][0].on,'Selection unexpectedly enabled FX');press(2,0);await until(()=>state.fx[0][0].on&&engine.fxChains.length>0,'Enable selected actual FX');report.fx={name:state.fx[0][0].name,on:state.fx[0][0].on,chains:engine.fxChains.length};click('#modal-close');click(button(0,'play'));await until(()=>source.playing,'FX source Play');event('delay-source');report.fxDuringPlay=JSON.parse(JSON.stringify(engine.fxState));await sleep(650);click(button(0,'play'));await until(()=>!source.playing,'Pause dry source');report.fxAfterPause=JSON.parse(JSON.stringify(engine.fxState));const tail=event('selected-delay-tail');await sleep(300);
  const blob=await engine.recordStop(),bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};const decoded=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));report.decoded={duration:decoded.duration,sampleRate:decoded.sampleRate,frames:decoded.length,channels:decoded.numberOfChannels};assert(decoded.numberOfChannels===2,'Expected stereo');for(let c=0;c<2;c++)for(const v of decoded.getChannelData(c))assert(Number.isFinite(v),'Nonfinite PCM');
  report.audio=[['single',single],['doubled',doubled],['tail',tail]].map(([name,e])=>({name,channels:[0,1].map(c=>measure(decoded.getChannelData(c),decoded.sampleRate,e.time+.08,e.time+.20))}));for(const w of report.audio)assert(Math.abs(w.channels[0].hz-330)<.8&&w.channels[0].rms>(w.name==='tail'?.0001:.005),w.name+' expected330Hz audio');const ratio=report.audio[1].channels[0].rms/report.audio[0].channels[0].rms;report.double.amplitudeRatio=ratio;assert(ratio>1.85&&ratio<2.15,'Doubled source is not approximately phase-aligned additive audio');
  report.checks=['Crate/track focus and fast browse reach actual lists, Prepare row/storage','Fixed4beat hardware Loop action is independent of Beat Jump setting','Double Load reaches playing source file/future clock and additive recorded audio','FX selectors reach Delay constructor and actual tail after source pause'];
 }catch(error){report.errors.push({message:error.message,stack:error.stack});}
 finally{
  engine.configureFX=configureFX;for(const d of state.decks)engine.pause(d);for(const bank of state.fx)for(const slot of bank)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],state.decks.map(d=>(d.track?.bpm||120)*d.rate),state.fxTempo);if(engine.recording){const blob=await engine.recordStop();if(blob){const bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};}}report.sourceAfter=await identities();report.sourceStable=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.completed=report.checks.length===4&&!report.errors.length&&report.sourceStable;report.finishedAt=new Date().toISOString();$('#everyday-original').textContent=JSON.stringify(report,null,2);$('#everyday-results').textContent=JSON.stringify({...report,recording:report.recording?{...report.recording,base64:'Retained in original JSON'}:null},null,2);$('#everyday-status').textContent=report.completed?'Scoped everyday-controls workflow passed; audio stopped':'Failed: '+report.errors.map(e=>e.message).join('; ');
 }
}
$('#everyday-run').onclick=()=>run();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#everyday-run').disabled=false;$('#everyday-run').textContent='Run one everyday-controls workflow';}
boot().catch(error=>$('#everyday-status').textContent=error.message);
